const allowedKeys = [
    'schema_version', 'event_at', 'review_id', 'event_category', 'event_type', 'action',
    'approver', 'actor_basis', 'status_before', 'status_after', 'token_state', 'result',
    'publish_result', 'http_method', 'http_status', 'service', 'service_operation',
    'service_status', 'service_result_code', 'external_reference', 'detail_code',
    'source_workflow_id', 'source_execution_id', 'source_node',
  ];
  const eventTypes = new Set([
    'AUDIT_TABLE_INITIALIZED', 'DRAFT_CREATED', 'INTAKE_DUPLICATE_REJECTED',
    'EMAIL_SEND_ATTEMPTED', 'EMAIL_SEND_SUCCEEDED', 'EMAIL_SEND_FAILED',
    'LINK_OPENED', 'LINK_INVALID', 'LINK_EXPIRED', 'LINK_REUSE_REJECTED',
    'DECISION_SUBMITTED', 'DECISION_INVALID', 'DECISION_INVALID_TOKEN',
    'DECISION_EXPIRED', 'TOKEN_REUSE_REJECTED', 'DECISION_RECORDED',
    'DUPLICATE_DECISION_REJECTED', 'HTTP_RESPONSE_SENT', 'HTTP_RESPONSE_FAILED',
  ]);
  const categories = new Set(['SYSTEM', 'INTAKE', 'EMAIL', 'REVIEW_LINK', 'DECISION', 'HTTP']);
  const actions = new Set(['', 'APPROVE', 'EDIT', 'SKIP']);
  const tokenStates = new Set(['', 'not_issued', 'issued', 'valid', 'invalid', 'expired', 'consumed', 'reused']);
  const results = new Set(['SUCCESS', 'REJECTED', 'FAILED', 'ATTEMPTED', 'PENDING', 'NOT_PUBLISHED']);
  const incoming = $json ?? {};
  const unknownKeys = Object.keys(incoming).filter((key) => !allowedKeys.includes(key));
  if (unknownKeys.length) throw new Error('Audit event contains unapproved fields.');
  const dangerousKey = Object.keys(incoming).find((key) =>
    !['token_state'].includes(key) && /(token|secret|password|cookie|authori[sz]ation|html|link|url|query|body|header)/i.test(key),
  );
  if (dangerousKey) throw new Error('Audit event contains a prohibited field name.');
  const clean = (name, max = 500) => {
    const value = String(incoming[name] ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, max);
    if (/(?:token=|access[_-]?token|refresh[_-]?token|bearer\s+[A-Za-z0-9._~+\/-]+=*|https?:\/\/\S+\?)/i.test(value)) {
      throw new Error('Audit event contains prohibited credential-like data.');
    }
    return value;
  };
  const reviewId = clean('review_id', 200);
  const eventType = clean('event_type', 80).toUpperCase();
  const category = clean('event_category', 40).toUpperCase();
  const action = clean('action', 20).toUpperCase();
  const tokenState = clean('token_state', 30).toLowerCase();
  const result = clean('result', 40).toUpperCase();
  const eventAt = clean('event_at', 64);
  const httpStatus = Number(incoming.http_status ?? 0);
  if (Number(incoming.schema_version) !== 1) throw new Error('Unsupported audit schema version.');
  if (!reviewId) throw new Error('Audit review_id is required.');
  if (!eventTypes.has(eventType)) throw new Error('Unsupported audit event type.');
  if (!categories.has(category)) throw new Error('Unsupported audit event category.');
  if (!actions.has(action)) throw new Error('Unsupported audit action.');
  if (!tokenStates.has(tokenState)) throw new Error('Unsupported audit token state.');
  if (!results.has(result)) throw new Error('Unsupported audit result.');
  if (!Number.isFinite(Date.parse(eventAt))) throw new Error('Invalid audit event timestamp.');
  if (!Number.isInteger(httpStatus) || (httpStatus !== 0 && (httpStatus < 100 || httpStatus > 599))) {
    throw new Error('Invalid audit HTTP status.');
  }
  const executionId = String($execution.id);
  return [{ json: {
    event_id: `FSV-AUDIT-${executionId}-${$itemIndex}`,
    schema_version: 1,
    event_at: eventAt,
    recorded_at: new Date().toISOString(),
    review_id: reviewId,
    event_category: category,
    event_type: eventType,
    action,
    approver: clean('approver', 254).toLowerCase(),
    actor_basis: clean('actor_basis', 80).toUpperCase(),
    status_before: clean('status_before', 80).toLowerCase(),
    status_after: clean('status_after', 80).toLowerCase(),
    token_state: tokenState,
    result,
    publish_result: clean('publish_result', 80).toLowerCase(),
    http_method: clean('http_method', 12).toUpperCase(),
    http_status: httpStatus,
    service: clean('service', 80).toUpperCase(),
    service_operation: clean('service_operation', 80).toUpperCase(),
    service_status: clean('service_status', 80).toUpperCase(),
    service_result_code: clean('service_result_code', 120).toUpperCase(),
    external_reference: clean('external_reference', 300),
    detail_code: clean('detail_code', 120).toUpperCase(),
    source_workflow_id: clean('source_workflow_id', 200),
    source_execution_id: clean('source_execution_id', 200),
    source_node: clean('source_node', 160),
    audit_execution_id: executionId,
  } }];

const event = $('Validate and Canonicalize Audit Event').item.json;
  return [{ json: {
    event_id: String(event.event_id),
    review_id: String(event.review_id),
    audit_write_status: 'APPENDED',
    audit_execution_id: String(event.audit_execution_id),
  } }];
